'use client'

import type { ReactNode, Ref } from 'react'
import { Switch as BaseSwitch } from '@base-ui/react/switch'
import { cn } from '@/lib/utils'
import { ChoiceField, choiceStyles, type ValidationState } from './ChoiceField'
import styles from './Switch.module.css'

export interface SwitchProps {
  ref?: Ref<HTMLElement>
  /** Controlled state. */
  checked?: boolean
  /** Uncontrolled starting state (the spec's `defaultValue`). */
  defaultChecked?: boolean
  /** The spec's `onChange`. Base UI's event details are dropped. */
  onCheckedChange?: (checked: boolean) => void
  label?: ReactNode
  helperText?: ReactNode
  name?: string
  /** Submitted when on; "on" by default, like a checkbox. */
  value?: string
  /**
   * Track 32×16 (`md`) or 40×20px (`lg`).
   * `sm` is deprecated: it draws the `md` track and goes in the next release.
   */
  size?: 'sm' | 'md' | 'lg'
  /** Colour of the on state. */
  variant?: 'primary' | 'accent' | 'destructive'
  disabled?: boolean
  required?: boolean
  readOnly?: boolean
  validationState?: ValidationState
  id?: string
  className?: string
  'aria-label'?: string
}

let hasWarned = false

export function Switch({
  label,
  helperText,
  name,
  size = 'md',
  variant = 'primary',
  disabled,
  required,
  validationState,
  className,
  onCheckedChange,
  ...props
}: SwitchProps) {
  if (import.meta.env.DEV && !hasWarned && size === 'sm') {
    hasWarned = true
    console.warn('Switch: `size="sm"` is deprecated and renders as `md`. It will be removed in the next release.')
  }
  return (
    <ChoiceField
      label={label}
      helperText={helperText}
      validationState={validationState}
      required={required}
      disabled={disabled}
      name={name}
      className={cn(styles[size === 'lg' ? 'lg' : 'md'], className)}
    >
      <BaseSwitch.Root
        {...props}
        required={required}
        onCheckedChange={onCheckedChange && ((next) => onCheckedChange(next))}
        className={cn(choiceStyles.control, styles.track, styles[variant])}
      >
        <BaseSwitch.Thumb className={styles.thumb} />
      </BaseSwitch.Root>
    </ChoiceField>
  )
}

/* Sizes are set on the field so the helper text can indent by the track's
   width. Doubled classes outrank ChoiceField's default, whichever
   stylesheet loads first. Two tracks, Atlassian's: 32×16 (md) and 40×20px
   (lg), each twice as wide as tall, so the thumb travels its own track
   height. sm is deprecated and draws the md track. */
.md.md {
  --choice-control: var(--switch-md-w);
  --choice-control-block: var(--switch-md-h);
}
.lg.lg {
  --choice-control: var(--switch-lg-w);
  --choice-control-block: var(--switch-lg-h);
}

/* Off: a --color-border-bold track (3:1 on the page, so the control is
   visible at all) with a page-coloured thumb. On: the variant's solid and
   its label colour, which is measured at 4.5:1 against it. */
.track {
  --switch-on: var(--color-background-brand-bold);
  --switch-on-thumb: var(--color-text-brand-inverse);
  display: inline-flex;
  align-items: center;
  inline-size: var(--choice-control);
  block-size: var(--choice-control-block);
  /* 2px between track edge and thumb at every size. */
  /* stylelint-disable-next-line scale-unlimited/declaration-strict-value -- see above */
  padding: 2px;
  border-radius: var(--radius-pill);
  background: var(--color-border-bold);
  cursor: var(--cursor-button);
  transition: background-color var(--duration-base);
}

.accent {
  --switch-on: var(--color-text);
  --switch-on-thumb: var(--color-surface);
}
.destructive {
  --switch-on: var(--color-background-danger-bold);
  --switch-on-thumb: var(--color-text-danger-inverse);
}

.track[data-checked] {
  background: var(--switch-on);
}

.track[data-readonly] {
  cursor: default;
}

/* Invalid: a 2px danger-coloured ring OUTSIDE the track, as Figma's
   outside stroke. It fills the --focus-offset gap, so the focus ring
   draws just beyond it and both show. The helper text says what is
   wrong. */
.track[data-invalid] {
  box-shadow: 0 0 0 2px var(--color-text-danger);
}

.thumb {
  block-size: calc(var(--choice-control-block) - 4px);
  aspect-ratio: 1;
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  transition:
    translate var(--duration-base),
    background-color var(--duration-base);
}

.thumb[data-checked] {
  /* The full travel: track width minus the thumb and both 2px gaps. */
  translate: calc(var(--choice-control) - var(--choice-control-block)) 0;
  background: var(--switch-on-thumb);
}

/* translate is physical; in a right-to-left page the thumb starts on the
   right and travels left. Not :dir(rtl): the build lowers it to a list of
   :lang()s, which misses a dir="rtl" page in any other language. */
:global([dir='rtl']) .thumb[data-checked] {
  translate: calc(var(--choice-control-block) - var(--choice-control)) 0;
}
:global([dir='rtl'] [dir='ltr']) .thumb[data-checked] {
  translate: calc(var(--choice-control) - var(--choice-control-block)) 0;
}
